// Solve solves an alphametics puzzle of the form "WORD1 + WORD2 + ... == RESULT".
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, " == ")
	if len(eq) != 2 {
		return nil, errors.New("invalid puzzle")
	}
	addends := strings.Split(eq[0], " + ")
	result := eq[1]

	words := append(append([]string{}, addends...), result)

	// Collect distinct letters.
	letters := map[string]bool{}
	for _, w := range words {
		for i := 0; i < len(w); i++ {
			letters[w[i:i+1]] = true
		}
	}
	if len(letters) > 10 {
		return nil, errors.New("no solution")
	}

	// Leading letters (first letter of a multi-letter word) cannot be zero.
	noZero := map[string]bool{}
	for _, w := range words {
		if len(w) > 1 {
			noZero[w[:1]] = true
		}
	}

	// Build columns, rightmost first.
